/*
 * prog41_series_sum.c
 *
 * Re‑implementation of the original binary (prog41_series_sum).
 *
 * The program expects two command‑line arguments:
 *
 *   1. mode  – an integer selecting the series to sum.
 *              1 :  Σ 1/(i*i)      (Basel series)
 *              3 :  Σ 1/i!         (e – series)
 *   2. limit – a non‑negative integer (maximum number of terms).
 *
 * Behaviour (exactly as the original binary):
 *
 *   • If fewer than two arguments are supplied → prints "NO_INPUT".
 *   • If either argument is not a pure decimal integer → prints "BAD_INPUT".
 *   • If limit > 100000 → prints "OUT_OF_RANGE".
 *   • If limit < 0 → prints "BAD_INPUT".
 *   • If mode == 1 → computes Σ_{i=1}^{limit} 1.0/(i*i) and prints it.
 *   • If mode == 3 → computes Σ_{i=0}^{limit} 1.0/i! (starting with 1) and prints it.
 *   • Any other mode → prints "BAD_MODE".
 *
 * All floating‑point results are printed with six digits after the decimal point,
 * exactly as the original program does (printf("%.6f\n", value);).
 *
 * The implementation follows the logic discovered in the decompiled state‑machine
 * of the original binary, including all error‑message strings and the 100 000
 * upper bound on the limit.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* -------------------------------------------------------------------- */
    /* 1. Argument count check                                               */
    /* -------------------------------------------------------------------- */
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    /* -------------------------------------------------------------------- */
    /* 2. Parse the two integer arguments safely                           */
    /* -------------------------------------------------------------------- */
    char *endptr;
    long mode, limit;

    errno = 0;
    mode = strtol(argv[1], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    errno = 0;
    limit = strtol(argv[2], &endptr, 10);
    if (errno != 0 || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    /* -------------------------------------------------------------------- */
    /* 3. Range checks for the limit                                        */
    /* -------------------------------------------------------------------- */
    if (limit < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (limit > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* -------------------------------------------------------------------- */
    /* 4. Choose the series according to the mode                           */
    /* -------------------------------------------------------------------- */
    double result = 0.0;

    if (mode == 1) {
        /* Basel series: Σ 1/(i*i) */
        for (long i = 1; i <= limit; ++i) {
            result += 1.0 / ((double)i * (double)i);
        }
    } else if (mode == 3) {
        /* e series: Σ 1/i!  (starting with i = 0) */
        double term = 1.0;          /* 1/0! */
        result = term;              /* start with the first term */
        for (long i = 1; i <= limit; ++i) {
            term /= (double)i;      /* term = 1/i! */
            result += term;
        }
    } else {
        puts("BAD_MODE");
        return 0;
    }

    /* -------------------------------------------------------------------- */
    /* 5. Output the computed sum                                            */
    /* -------------------------------------------------------------------- */
    printf("%.6f\n", result);
    return 0;
}
